{
  "items": [
    {
      "name": "Finsupp.sum_of_support_subset",
      "type": " {α : Type u_1} {M : Type u_8} {N : Type u_10} [Zero M] [AddCommMonoid N] (f : α →₀ M) {s : Finset α} (hs : f.support ⊆ s) (g : α → M → N) (h : ∀ i ∈ s, g i 0 = 0) : f.sum g = ∑ x ∈ s, g x (f x)",
      "module": "Mathlib.Algebra.BigOperators.Finsupp.Basic"
    },
    {
      "name": "Finsupp.support_sum",
      "type": " {α : Type u_1} {β : Type u_7} {M : Type u_8} {N : Type u_10} [DecidableEq β] [Zero M] [AddCommMonoid N] {f : α →₀ M} {g : α → M → β →₀ N} : (f.sum g).support ⊆ f.support.biUnion fun a => (g a (f a)).support",
      "module": "Mathlib.Algebra.BigOperators.Finsupp.Basic"
    },
    {
      "name": "Submodule.mem_span_set",
      "type": " {R : Type u_1} {M : Type u_2} [Semiring R] [AddCommMonoid M] [Module R M] {m : M} {s : Set M} : m ∈ Submodule.span R s ↔ ∃ c, ↑c.support ⊆ s ∧ (c.sum fun mi r => r • mi) = m",
      "module": "Mathlib.LinearAlgebra.Finsupp.LinearCombination"
    },
    {
      "name": "Submodule.mem_set_smul",
      "type": " {R : Type u_2} {M : Type u_3} [Semiring R] [AddCommMonoid M] [Module R M] (sR : Set R) (N : Submodule R M) (x : M) [SMulCommClass R R ↥N] : x ∈ sR • N ↔ ∃ c, ↑c.support ⊆ sR ∧ x = ↑(c.sum fun r m => r • m)",
      "module": "Mathlib.Algebra.Module.Submodule.Finsupp"
    },
    {
      "name": "Submodule.mem_span_set_iff_exists_finsupp_le_finrank",
      "type": " {K : Type u_2} {M : Type u_3} [DivisionRing K] [AddCommGroup M] [Module K M] {s : Set M} {x : M} [Module.Finite K ↥(Submodule.span K s)] : x ∈ Submodule.span K s ↔ ∃ c, c.support.card ≤ Module.finrank K ↥(Submodule.span K s) ∧ ↑c.support ⊆ s ∧ (c.sum fun mi r => r • mi) = x",
      "module": "Mathlib.LinearAlgebra.Dimension.StrongRankCondition"
    }
  ]
}
